    def numberOfRightTriangles(self, grid: List[List[int]]) -> int:
        count = 0
        rows = len(grid)
        cols = len(grid[0])
        for i in range(rows):
            for j in range(cols):
                if grid[i][j] == 1:
                    # find pairs of points with 1 on same row
                    for c in range(cols):
                        if c != j and grid[i][c] == 1:
                            # find points on same column as c but different row
                            for r in range(rows):
                                if r != i and grid[r][c] == 1:
                                    count += 1
        return count"}
